T.append(L(P+"t07","Asymptotic Notations: Big Oh, Big Omega & Big Theta","high",
"Asymptotic notations describe the growth rate of a function for large n: Big Oh (upper bound), Big Omega (lower bound) and Big Theta (tight bound).",
"Asymptotic notation batata hai n bahut bada hone par function kitni tezi se badhta hai. O = upper limit, Ω = lower limit, Θ = dono (tight).",
"Speed limits: O = 'not faster than' a maximum, Ω = 'at least' a minimum, Θ = exactly in this range.",
"f(n)=3n+2. O(n): 3n+2 ≤ 4n for n≥2 (c=4, n0=2). Ω(n): 3n+2 ≥ 3n for n≥1 (c=3). Hence Θ(n).",
["f(n)=O(g(n)) if ∃ c>0, n0: f(n) ≤ c·g(n) ∀ n ≥ n0.","f(n)=Ω(g(n)) if f(n) ≥ c·g(n) ∀ n ≥ n0.","f(n)=Θ(g(n)) if c1·g(n) ≤ f(n) ≤ c2·g(n) ∀ n ≥ n0 (both O and Ω).","Growth order: 1 < log n < n < n log n < n² < n³ < 2ⁿ < n!.","Drop constants and lower-order terms.","Little-o and little-ω denote strict bounds."],
["Three formal definitions.","Proof with c and n0.","Growth order."],
["Prove f(n)=O(g(n)).","State definitions.","Order functions by growth."],
["Saying O is the exact complexity (that is Θ).","Forgetting to give c and n0 in proofs."],
[E("numerical","Show 3n+2 = Θ(n).","3n ≤ 3n+2 ≤ 4n for n ≥ 2 ⇒ Θ(n)."),
 E("definition","Define Big O, Ω, Θ.","As above with c and n0."),
 E("viva","Is n² = O(n³)?","Yes, O is an upper bound (not tight).")],
[Q("MCQ","Tight bound notation:","Θ","",["O","Ω","Θ","o"]),
 Q("true/false","2n+5 = O(n).","True",""),
 Q("problem solving","Find c, n0 for 5n+3 = O(n).","c=6, n0=3","5n+3 ≤ 6n for n≥3."),
 Q("short answer","Order n log n vs n².","n log n grows slower.",""),
 Q("comparison","O vs Ω.","O upper bound; Ω lower bound.","")],
"O: f≤c·g (upper); Ω: f≥c·g (lower); Θ: both (tight); drop constants; 1<log n<n<n log n<n²<2ⁿ<n!.",
workedExample="3n+2: choose c=4, n0=2 → 3n+2 ≤ 4n ✓ (O(n)); c=3 → 3n+2 ≥ 3n ✓ (Ω(n)); so Θ(n).",
comparison=CMP("Notations",["Notation","Meaning","Bound"],[["O(g)","f ≤ c g","Upper"],["Ω(g)","f ≥ c g","Lower"],["Θ(g)","c1 g ≤ f ≤ c2 g","Tight"]])))
